// PCA tests.
//
// Parity goldens were generated by upstream `vcftools 0.1.18` rebuilt with
// `--enable-pca` and linked against `liblapack`/`libblas` on Ubuntu 24.04
// (see /tmp/vcftools_lapack_install in the dev sandbox). Regenerate with:
//
//	cd reference_code/vcftools && ./configure --enable-pca \
//	    CFLAGS="-O2 -U_FORTIFY_SOURCE" CXXFLAGS="-O2 -U_FORTIFY_SOURCE" && \
//	    make && make install prefix=/tmp/vcftools_lapack_install
//	/tmp/vcftools_lapack_install/bin/vcftools \
//	    --vcf tools/vcftools/testdata/parity/pca_basic.vcf \
//	    --pca --out /tmp/regen
//
// Eigenvector signs differ between LAPACK implementations (and our gonum
// path canonicalises signs to "first nonzero positive"); parity tests
// therefore compare with sign-tolerant equality on the eigenvector rows.
// Eigenvalues — which are sign-invariants — are compared with a tight
// numerical tolerance.
package vcftools

import (
	"bufio"
	"math"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
)

const pcaBasicVCF = "##fileformat=VCFv4.2\n" +
	"##FORMAT=<ID=GT,Number=1,Type=String,Description=\"GT\">\n" +
	"#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\tFORMAT\ts1\ts2\ts3\n" +
	"1\t100\t.\tA\tG\t.\tPASS\t.\tGT\t0/0\t0/1\t1/1\n" +
	"1\t200\t.\tA\tC\t.\tPASS\t.\tGT\t0/1\t0/1\t1/1\n" +
	"1\t300\t.\tA\tT\t.\tPASS\t.\tGT\t0/0\t1/1\t0/1\n" +
	"1\t400\t.\tA\tG\t.\tPASS\t.\tGT\t1/1\t0/1\t0/0\n"

// TestPCA_BasicEigenvaluesAndShape covers the algebraic properties of the
// computed eigendecomposition without depending on sign or LAPACK
// implementation: eigenvalues are non-negative, sum equals the trace of
// the GRM, and N eigenvalues / eigenvectors are emitted for N kept
// individuals.
func TestPCA_BasicEigenvaluesAndShape(t *testing.T) {
	dir := t.TempDir()
	prefix := filepath.Join(dir, "out")
	params := &Params{OutPrefix: prefix, PCA: true}
	if err := Run(strings.NewReader(pcaBasicVCF), params); err != nil {
		t.Fatalf("Run: %v", err)
	}
	vals, vecs, names := readPCAFile(t, prefix+".pca")

	if len(names) != 3 || names[0] != "s1" || names[1] != "s2" || names[2] != "s3" {
		t.Errorf("indv names = %v, want [s1 s2 s3]", names)
	}
	if len(vals) != 3 {
		t.Fatalf("got %d eigenvalues, want 3", len(vals))
	}
	// Centred GRM is positive semi-definite → no negative eigenvalues
	// beyond machine epsilon.
	for i, v := range vals {
		if v < -1e-9 {
			t.Errorf("eigenvalue %d = %g; want >= 0", i, v)
		}
	}
	// Sorted by |val| descending.
	for i := 1; i < len(vals); i++ {
		if math.Abs(vals[i-1]) < math.Abs(vals[i]) {
			t.Errorf("eigenvalues not sorted by |.| desc: %v", vals)
			break
		}
	}
	// Eigenvector rows should be unit-norm (orthonormal columns). We
	// read back the 6-sig-fig formatted output, so the round-trip
	// loses ~1e-6 precision — looser tolerance than the underlying
	// gonum computation provides.
	for j := 0; j < 3; j++ {
		var norm2 float64
		for i := 0; i < 3; i++ {
			norm2 += vecs[i][j] * vecs[i][j]
		}
		if math.Abs(norm2-1.0) > 1e-5 {
			t.Errorf("eigenvector column %d not unit norm: ||v||² = %g", j, norm2)
		}
	}
}

// TestPCA_NoNormChangesEigenvalues — passing --pca-no-norm should
// produce numerically different eigenvalues from the default --pca
// run, because variance normalisation is what makes per-SNP
// contributions commensurate. Both runs should still pass the
// trace / non-negative checks.
func TestPCA_NoNormChangesEigenvalues(t *testing.T) {
	dir := t.TempDir()
	pNorm := filepath.Join(dir, "norm")
	pNoNorm := filepath.Join(dir, "nonorm")

	if err := Run(strings.NewReader(pcaBasicVCF), &Params{OutPrefix: pNorm, PCA: true}); err != nil {
		t.Fatalf("Run --pca: %v", err)
	}
	if err := Run(strings.NewReader(pcaBasicVCF), &Params{OutPrefix: pNoNorm, PCANoNorm: true}); err != nil {
		t.Fatalf("Run --pca-no-norm: %v", err)
	}

	v1, _, _ := readPCAFile(t, pNorm+".pca")
	v2, _, _ := readPCAFile(t, pNoNorm+".pca")

	// Leading eigenvalue should differ by more than tolerance.
	if math.Abs(v1[0]-v2[0]) < 1e-6 {
		t.Errorf("--pca and --pca-no-norm produced same leading eigenvalue (%g vs %g)", v1[0], v2[0])
	}
}

// TestPCA_SNPLoadingsOnlyDoesNotWritePCAFile — `--pca-snp-loadings INT`
// alone (without --pca) must NOT emit `.pca`, matching upstream's
// vcftools.cpp:110-111 dispatch where output_PCA and
// output_N_PCA_SNP_loadings trigger independent calls.
func TestPCA_SNPLoadingsOnlyDoesNotWritePCAFile(t *testing.T) {
	dir := t.TempDir()
	prefix := filepath.Join(dir, "out")
	if err := Run(strings.NewReader(pcaBasicVCF), &Params{OutPrefix: prefix, PCASNPLoadings: 2}); err != nil {
		t.Fatalf("Run: %v", err)
	}
	if _, err := os.Stat(prefix + ".pca"); err == nil {
		t.Errorf("--pca-snp-loadings alone wrote a .pca file; expected only .pca.loadings")
	}
	if _, err := os.Stat(prefix + ".pca.loadings"); err != nil {
		t.Errorf("--pca-snp-loadings did not write .pca.loadings: %v", err)
	}
}

// TestPCA_MonomorphicSitesDropped covers the upstream check at
// variant_file_output.cpp:4948-4949: sites with allele frequency at
// machine-epsilon bounds (i.e. all-ref or all-alt) are skipped, not
// included in the GRM. Adds two monomorphic sites to the basic fixture
// and confirms eigenvalues match the basic-fixture run (i.e. the
// monomorphic sites were dropped).
func TestPCA_MonomorphicSitesDropped(t *testing.T) {
	withMonomorphic := pcaBasicVCF +
		"1\t500\t.\tA\tG\t.\tPASS\t.\tGT\t0/0\t0/0\t0/0\n" + // all-ref
		"1\t600\t.\tA\tG\t.\tPASS\t.\tGT\t1/1\t1/1\t1/1\n" // all-alt
	dir := t.TempDir()
	pBase := filepath.Join(dir, "base")
	pMono := filepath.Join(dir, "mono")
	if err := Run(strings.NewReader(pcaBasicVCF), &Params{OutPrefix: pBase, PCA: true}); err != nil {
		t.Fatalf("Run base: %v", err)
	}
	if err := Run(strings.NewReader(withMonomorphic), &Params{OutPrefix: pMono, PCA: true}); err != nil {
		t.Fatalf("Run mono: %v", err)
	}
	vBase, _, _ := readPCAFile(t, pBase+".pca")
	vMono, _, _ := readPCAFile(t, pMono+".pca")
	if len(vBase) != len(vMono) {
		t.Fatalf("eigenvalue count differs: base=%d mono=%d", len(vBase), len(vMono))
	}
	for i := range vBase {
		if math.Abs(vBase[i]-vMono[i]) > 1e-9 {
			t.Errorf("eigenvalue %d: base=%g mono=%g (monomorphic sites changed the spectrum)", i, vBase[i], vMono[i])
		}
	}
}

// TestPCA_MissingDataSkipsSite is the wave-19 fix-on-port. A site with
// any kept-indv missing genotype is dropped (rather than producing the
// jagged-M[i] indexing bug upstream has). Adds one such site and
// confirms eigenvalues still match the basic-fixture run.
func TestPCA_MissingDataSkipsSite(t *testing.T) {
	withMissing := pcaBasicVCF +
		"1\t500\t.\tA\tG\t.\tPASS\t.\tGT\t0/0\t./.\t1/1\n"
	dir := t.TempDir()
	pBase := filepath.Join(dir, "base")
	pMiss := filepath.Join(dir, "miss")
	if err := Run(strings.NewReader(pcaBasicVCF), &Params{OutPrefix: pBase, PCA: true}); err != nil {
		t.Fatalf("Run base: %v", err)
	}
	if err := Run(strings.NewReader(withMissing), &Params{OutPrefix: pMiss, PCA: true}); err != nil {
		t.Fatalf("Run miss: %v", err)
	}
	vBase, _, _ := readPCAFile(t, pBase+".pca")
	vMiss, _, _ := readPCAFile(t, pMiss+".pca")
	for i := range vBase {
		if math.Abs(vBase[i]-vMiss[i]) > 1e-9 {
			t.Errorf("eigenvalue %d: base=%g miss=%g (missing site was not skipped)", i, vBase[i], vMiss[i])
		}
	}
}

// TestPCA_NonBiallelicErrors confirms a tri-allelic site errors out
// rather than being silently included, mirroring upstream's
// variant_file_output.cpp:4939 LOG.error.
func TestPCA_NonBiallelicErrors(t *testing.T) {
	// Note: upstream's `--pca` sets min_alleles=2 / max_alleles=2
	// (parameters.cpp:298), which filters tri-allelic sites before
	// they reach output_PCA. This port does not auto-set that filter
	// (the user passes --max-alleles explicitly if they want it), so
	// the tri-allelic site reaches the PCA runner and the biallelic
	// check at variant_file_output.cpp:4939 fires here.
	triallelic := "##fileformat=VCFv4.2\n" +
		"##FORMAT=<ID=GT,Number=1,Type=String,Description=\"GT\">\n" +
		"#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\tFORMAT\ts1\ts2\ts3\n" +
		"1\t100\t.\tA\tG,T\t.\tPASS\t.\tGT\t0/1\t1/2\t2/2\n" +
		"1\t200\t.\tA\tC\t.\tPASS\t.\tGT\t0/1\t0/1\t1/1\n" +
		"1\t300\t.\tA\tT\t.\tPASS\t.\tGT\t0/0\t1/1\t0/1\n" +
		"1\t400\t.\tA\tG\t.\tPASS\t.\tGT\t1/1\t0/1\t0/0\n"
	dir := t.TempDir()
	prefix := filepath.Join(dir, "out")
	err := Run(strings.NewReader(triallelic), &Params{OutPrefix: prefix, PCA: true})
	if err == nil {
		t.Fatal("expected error on tri-allelic site; got nil")
	}
	if !strings.Contains(err.Error(), "biallelic") {
		t.Errorf("error %q: want substring %q", err.Error(), "biallelic")
	}
}

// TestPCA_TooFewSites checks the "PCA computation requires that there are
// more sites than individuals" guard (variant_file_output.cpp:4975-4976).
// 3 samples × 2 (non-monomorphic) sites must error.
func TestPCA_TooFewSites(t *testing.T) {
	tooFew := "##fileformat=VCFv4.2\n" +
		"##FORMAT=<ID=GT,Number=1,Type=String,Description=\"GT\">\n" +
		"#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\tFORMAT\ts1\ts2\ts3\n" +
		"1\t100\t.\tA\tG\t.\tPASS\t.\tGT\t0/0\t0/1\t1/1\n" +
		"1\t200\t.\tA\tC\t.\tPASS\t.\tGT\t0/1\t0/1\t1/1\n"
	dir := t.TempDir()
	prefix := filepath.Join(dir, "out")
	err := Run(strings.NewReader(tooFew), &Params{OutPrefix: prefix, PCA: true})
	if err == nil {
		t.Fatal("expected error for N_sites <= N_indvs; got nil")
	}
	if !strings.Contains(err.Error(), "more sites than individuals") {
		t.Errorf("error %q: want substring %q", err.Error(), "more sites than individuals")
	}
}

// TestParity_PCA_Basic compares the port's --pca output against the
// upstream-generated golden, ignoring eigenvector sign per the file
// header note.
func TestParity_PCA_Basic(t *testing.T) {
	runAndCompareWithSign(t, "pca_basic.vcf", "pca_basic.expected.pca",
		&Params{PCA: true},
		".pca")
}

// TestParity_PCA_NoNorm covers --pca-no-norm parity.
func TestParity_PCA_NoNorm(t *testing.T) {
	runAndCompareWithSign(t, "pca_basic.vcf", "pca_basic_nonorm.expected.pca",
		&Params{PCANoNorm: true},
		".pca")
}

// TestParity_PCA_SNPLoadings covers --pca-snp-loadings parity. The
// GAMMA columns are sign-correlated with the eigenvector signs (numerator
// is x * Evecs[i][k]; denominator squares Evecs out), so the same
// sign-tolerant comparison applies per loading column.
func TestParity_PCA_SNPLoadings(t *testing.T) {
	runAndCompareWithSign(t, "pca_basic.vcf", "pca_basic.expected.pca.loadings",
		&Params{PCASNPLoadings: 2},
		".pca.loadings")
}

// runAndCompareWithSign runs the port with `params` against fixture
// `vcfName` (under testdata/parity/), compares the named output file
// to `goldenName` with eigenvalue/eigenvector-component matching
// (numerical tolerance + per-column sign tolerance).
func runAndCompareWithSign(t *testing.T, vcfName, goldenName string, params *Params, suffix string) {
	t.Helper()
	dir := t.TempDir()
	prefix := filepath.Join(dir, "out")
	params.OutPrefix = prefix

	fixturePath := filepath.Join(vcftoolsFixtureDir(t), vcfName)
	in, err := os.Open(fixturePath)
	if err != nil {
		t.Fatalf("open fixture: %v", err)
	}
	defer in.Close()
	if err := Run(in, params); err != nil {
		t.Fatalf("Run: %v", err)
	}

	got := readPCATable(t, prefix+suffix)
	want := readPCATable(t, filepath.Join(vcftoolsFixtureDir(t), goldenName))

	if len(got.header) != len(want.header) {
		t.Fatalf("header length: got %d want %d (%q vs %q)", len(got.header), len(want.header), got.header, want.header)
	}
	for i := range got.header {
		if got.header[i] != want.header[i] {
			t.Errorf("header[%d]: got %q want %q", i, got.header[i], want.header[i])
		}
	}
	if len(got.labels) != len(want.labels) {
		t.Fatalf("row count: got %d want %d", len(got.labels), len(want.labels))
	}
	for i := range got.labels {
		if got.labels[i] != want.labels[i] {
			t.Errorf("row label[%d]: got %q want %q", i, got.labels[i], want.labels[i])
		}
	}

	// Per-column sign tolerance: each numeric column may be globally
	// negated (eigenvector / loading sign ambiguity). For each column,
	// find the first row whose |got| > tol and compare its sign with
	// want; if opposite, all subsequent comparisons in that column
	// negate `got`.
	const tol = 1e-5
	numCols := len(got.data[0])
	for j := 0; j < numCols; j++ {
		signFlip := false
		isEigVal := want.labels[0] == "EIGENVALUE" && j == 0 // not actually a column index, see below
		_ = isEigVal
		// Determine sign flip from first non-zero row in this column.
		// Eigenvalues (the "EIGENVALUE" row) are sign-invariant — skip
		// the flip decision until we see a true eigenvector row.
		startRow := 0
		if want.labels[0] == "EIGENVALUE" {
			startRow = 1
		}
		for i := startRow; i < len(got.data); i++ {
			if math.Abs(got.data[i][j]) > tol && math.Abs(want.data[i][j]) > tol {
				if (got.data[i][j] < 0) != (want.data[i][j] < 0) {
					signFlip = true
				}
				break
			}
		}
		for i := 0; i < len(got.data); i++ {
			g := got.data[i][j]
			w := want.data[i][j]
			// Eigenvalue row: no sign flip applied; allow looser
			// near-zero tolerance.
			if want.labels[0] == "EIGENVALUE" && i == 0 {
				if math.Abs(w) < 1e-10 {
					// Both near-zero — fine.
					if math.Abs(g) > 1e-9 {
						t.Errorf("row %s col %d: got %g want ~0", got.labels[i], j, g)
					}
					continue
				}
				if math.Abs(g-w) > 1e-5*math.Max(1.0, math.Abs(w)) {
					t.Errorf("row %s col %d: got %g want %g", got.labels[i], j, g, w)
				}
				continue
			}
			if signFlip {
				g = -g
			}
			if math.Abs(g-w) > tol {
				t.Errorf("row %s col %d: got %g want %g (signFlip=%v)", got.labels[i], j, g, w, signFlip)
			}
		}
	}
}

type pcaTable struct {
	header []string
	labels []string // first column of each row
	data   [][]float64
}

// readPCATable parses a vcftools .pca or .pca.loadings file. Both share
// the same shape: tab-separated header, then N tab-separated rows where
// column 0 is a string label and columns 1.. are floats.
func readPCATable(t *testing.T, path string) *pcaTable {
	t.Helper()
	f, err := os.Open(path)
	if err != nil {
		t.Fatalf("open %s: %v", path, err)
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	var tab pcaTable
	first := true
	for scanner.Scan() {
		fields := strings.Split(scanner.Text(), "\t")
		if first {
			tab.header = fields
			first = false
			continue
		}
		tab.labels = append(tab.labels, fields[0])
		row := make([]float64, len(fields)-1)
		for i, s := range fields[1:] {
			v, err := strconv.ParseFloat(s, 64)
			if err != nil {
				t.Fatalf("parse %s field %q: %v", path, s, err)
			}
			row[i] = v
		}
		tab.data = append(tab.data, row)
	}
	if err := scanner.Err(); err != nil {
		t.Fatalf("scan %s: %v", path, err)
	}
	return &tab
}

// readPCAFile is the helper used by TestPCA_BasicEigenvaluesAndShape.
// It returns the eigenvalues, eigenvector matrix (vecs[i][j] = i-th
// component of j-th eigenvector), and individual names.
func readPCAFile(t *testing.T, path string) (vals []float64, vecs [][]float64, names []string) {
	t.Helper()
	tab := readPCATable(t, path)
	if len(tab.labels) == 0 || tab.labels[0] != "EIGENVALUE" {
		t.Fatalf("%s: first row label is %q, want EIGENVALUE", path, tab.labels[0])
	}
	vals = tab.data[0]
	for i := 1; i < len(tab.labels); i++ {
		names = append(names, tab.labels[i])
		vecs = append(vecs, tab.data[i])
	}
	return vals, vecs, names
}
